#include "can_v_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void can_v_rx_init_os_interface (void)
{
  Can_V_Rx curr ;
  Can_V_Rx next ;

  for (curr = can_v_vars.init.can_v_rx_list ; curr ; curr = next)
    {
      UInt16 rx_q_size = curr->obj.init.rx_q_size ;

      next = curr->obj.init.next ;

      curr->obj.exec.q_rcev = os_mbx_create () ;
      curr->obj.exec.q_free = os_mbx_create () ;

      while (rx_q_size--)
        {
          os_mbx_send (curr->obj.exec.q_free , (MbxMsg *) os_mem_request (sizeof (Rx_Q_Msg))) ;
        }
    }
}

